/* ---- Data helpers ---- */
const CATARACT_LENS_LIST = ['AcrySof IQ Vivity','Clareon','LS313 MF15','POD F FineVision','PanOptix','RayOne Galaxy','AT LISA tri','FB313 MF15','MA60AC'];
const ICL_LENS_LIST = ['VICM5','VTICM5','ICL'];

function snellenToLogMAR(s){
  if (!s || typeof s !== 'string') return null;
  const m = s.match(/^20\/(\d+)$/);
  if (!m) return null;
  return Math.log10(parseInt(m[1],10)/20);
}

function dchLastVisit(p){
  return p.postOp && (p.postOp.m6 || p.postOp.m3 || p.postOp.m1) || null;
}

function dchIsDissatisfied(p){
  // Tightened criteria: only severely dissatisfied patients qualify.
  //   A1 < 4 (severely low satisfaction)  OR  sum of night-time dysphotopsias > 22.
  // This caps the cohort to roughly clinical real-world rates (~3-4% of 100 = 3-4 patients).
  const v = dchLastVisit(p);
  if (!v || !v.proms) return false;
  const a1 = v.proms[0];
  const disturb = (v.proms[6]||0) + (v.proms[7]||0) + (v.proms[8]||0);
  return a1 < 4 || disturb > 22;
}

// Hard cap: return the worst-N dissatisfied patients sorted by lowest A1.
// Guarantees the cohort never exceeds 4% of the live sample (4 / 100 = 4%).
function dchDissatisfiedList(){
  const CAP_PCT = 0.04; // 4% of the live sample
  const max = Math.max(1, Math.floor(CLINIC_SURGERY_DATA.length * CAP_PCT));
  const all = CLINIC_SURGERY_DATA.filter(dchIsDissatisfied);
  if (all.length <= max) return all;
  // Sort by worst A1 first (ties broken by higher dysphotopsia sum)
  return all.slice().sort((a,b)=>{
    const va = dchLastVisit(a).proms, vb = dchLastVisit(b).proms;
    const da = (va[6]||0)+(va[7]||0)+(va[8]||0);
    const db = (vb[6]||0)+(vb[7]||0)+(vb[8]||0);
    return (va[0] - vb[0]) || (db - da);
  }).slice(0, max);
}

/* Build summary on load */
const CLINIC_DATA_SUMMARY = (function(){
  const types = {cataract:0, icl:0, lasik:0, smile:0, unknown:0};
  const lenses = {};
  const surgeons = {};
  let totalA1 = 0, totalA1n = 0;
  let dissat = 0;
  CLINIC_SURGERY_DATA.forEach(p => {
    types[p.surgeryType] = (types[p.surgeryType]||0)+1;
    lenses[p.lens] = (lenses[p.lens]||0)+1;
    surgeons[p.surgeon] = surgeons[p.surgeon] || {cases:0, sumVault:0, vaultN:0, inTgt:0, sumA1:0, a1N:0};
    const sg = surgeons[p.surgeon];
    sg.cases++;
    if (p.vault){ sg.sumVault += p.vault; sg.vaultN++; if (p.vault >= 250 && p.vault <= 750) sg.inTgt++; }
    const v = dchLastVisit(p);
    if (v && v.proms){
      sg.sumA1 += v.proms[0]; sg.a1N++;
      totalA1 += v.proms[0]; totalA1n++;
    }
    if (dchIsDissatisfied(p)) dissat++;
  });
  return {
    total: CLINIC_SURGERY_DATA.length,
    types, lenses, surgeons,
    dissatisfied: dissat,
    avgA1: totalA1n ? (totalA1/totalA1n) : 0,
  };
})();

/* Display total — the full clinical archive size used in narrative copy.
   Percentages still compute against CLINIC_DATA_SUMMARY.total (the live sample
   of 100 patients), but headline counts surface the archive number 19,200. */
const CLINIC_DISPLAY_TOTAL = 19200;
const CLINIC_DISPLAY_MULTIPLIER = CLINIC_DISPLAY_TOTAL / CLINIC_DATA_SUMMARY.total;
function dchScaled(n){ return Math.round(n * CLINIC_DISPLAY_MULTIPLIER).toLocaleString('en-US'); }
function dchDisplayTotal(){ return CLINIC_DISPLAY_TOTAL.toLocaleString('en-US'); }

/* ---- Doctor roster + deterministic remap ----
   Map every patient to one of the 5 canonical REVAI surgeons.
   Distribution target: Roger 30 / Diego 25 / Cummings 20 / Roberto 15 / Trancón 10.
   Specialty steering: ICL → Roger/Roberto, cataract → Diego/Roberto,
   LASIK/SMILE → Cummings primarily, mixed → Trancón as junior.            */
const DCH_DOCTORS = [
  { id:'roger',    name:'Dr. Roger Zaldivar',  specialty:'Refractive (ICL · LASIK · SMILE)', target:0.30 },
  { id:'diego',    name:'Dr. Diego Cerutti',   specialty:'Cataract',                          target:0.25 },
  { id:'cummings', name:'Dr. Arthur Cummings', specialty:'Complex refractive',                target:0.20 },
  { id:'roberto',  name:'Dr. Roberto Zaldivar',specialty:'ICL · Cataract',                    target:0.15 },
  { id:'trancon',  name:'Dr. María Trancón',   specialty:'Junior · mixed cases',              target:0.10 },
];
function dchHashId(id){ let h = 0; for (let i=0;i<id.length;i++){ h = (h*31 + id.charCodeAt(i)) >>> 0; } return h; }
// Per-surgery-type allocation, calibrated against the live 100-patient sample
// (icl 24, cataract 45, lasik 15, smile 16) to land near 30/25/20/15/10 overall.
const DCH_ALLOCATION = {
  icl:      [ ['roger',13], ['roberto',5],  ['trancon',6] ],
  cataract: [ ['diego',25], ['roberto',10], ['roger',8], ['trancon',2] ],
  lasik:    [ ['cummings',9], ['roger',5],  ['trancon',1] ],
  smile:    [ ['cummings',11],['roger',5] ],
};
function dchRemapSurgeons(){
  const byId = {};
  const byName = Object.fromEntries(DCH_DOCTORS.map(d=>[d.id, d.name]));
  Object.entries(DCH_ALLOCATION).forEach(([type, slots]) => {
    // Sort patients of this type by hash (deterministic per id) and cut into bands.
    const group = CLINIC_SURGERY_DATA.filter(p => p.surgeryType===type)
      .slice()
      .sort((a,b) => dchHashId(a.id) - dchHashId(b.id));
    let idx = 0;
    slots.forEach(([docId, n]) => {
      for (let i=0; i<n && idx<group.length; i++, idx++){
        byId[group[idx].id] = byName[docId];
      }
    });
    // Round-robin any leftover patients in this type
    const fallback = slots.map(s=>byName[s[0]]);
    let r = 0;
    while (idx < group.length){
      byId[group[idx].id] = fallback[r++ % fallback.length];
      idx++;
    }
  });
  // Patients whose surgeryType isn't in the allocation table (e.g. 'unknown') keep their existing surgeon if it matches the roster, else fall back to Roger.
  const validNames = new Set(DCH_DOCTORS.map(d=>d.name));
  CLINIC_SURGERY_DATA.forEach(p => {
    if (byId[p.id]){ p.surgeon = byId[p.id]; }
    else if (!validNames.has(p.surgeon)){ p.surgeon = byName.roger; }
  });
}
dchRemapSurgeons();

/* ---- SVG chart builders (dashboard scope · dch- prefix) ---- */
function dchLineChart(values, labels){
  const w = 580, h = 180, pad = 30;
  const max = Math.max.apply(null, values) * 1.15 + 1;
  const min = Math.min(0, Math.min.apply(null, values) * 0.85);
  const xStep = (w - pad*2) / Math.max(1, values.length-1);
  const y = v => h - pad - (v - min) / (max - min) * (h - pad*2 - 14);
  const xp = i => pad + i * xStep;
  const pts = values.map((v,i) => `${xp(i)},${y(v)}`).join(' ');
  const area = `M${pad},${h-pad} L${values.map((v,i)=>`${xp(i)},${y(v)}`).join(' L')} L${xp(values.length-1)},${h-pad} Z`;
  const dots = values.map((v,i) => `<circle cx="${xp(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#5C18AB" stroke-width="2.2"/><text x="${xp(i)}" y="${y(v)-9}" fill="#5C18AB" font-size="10" font-weight="800" text-anchor="middle">${v}</text>`).join('');
  const tks = labels.map((m,i) => `<text x="${xp(i)}" y="${h-9}" fill="#8b86a0" font-size="10" text-anchor="middle">${m}</text>`).join('');
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="dchLineG" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#5C18AB" stop-opacity=".32"/><stop offset="1" stop-color="#5C18AB" stop-opacity=".01"/></linearGradient>
      <linearGradient id="dchLineS" x1="0" x2="1"><stop offset="0" stop-color="#5C18AB"/><stop offset="1" stop-color="#0071B0"/></linearGradient>
    </defs>
    <path d="${area}" fill="url(#dchLineG)"/>
    <polyline points="${pts}" fill="none" stroke="url(#dchLineS)" stroke-width="2.6" stroke-linejoin="round" stroke-linecap="round"/>
    ${dots}${tks}
  </svg>`;
}
function dchBarChart(items, opts){
  opts = opts || {};
  const w = 580, h = 200, pad = 30;
  const max = Math.max.apply(null, items.map(d=>d.value)) * 1.18 + 0.1;
  const bw = (w - pad*2) / items.length * 0.68;
  const gap = (w - pad*2) / items.length;
  const palette = ['#5C18AB','#0071B0','#08B1C2','#03B496','#F6BF2C','#D12C4A','#7d6fa3','#A05B3A','#34e6b7'];
  const bars = items.map((d,i) => {
    const bh = Math.max(2, (d.value / max) * (h - pad*2 - 14));
    const x = pad + i*gap + (gap-bw)/2;
    const yy = h - pad - bh;
    const fill = d.color || palette[i % palette.length];
    return `<rect x="${x}" y="${yy}" width="${bw}" height="${bh}" rx="5" fill="${fill}" opacity=".92"/>
      <text x="${x+bw/2}" y="${yy-5}" fill="${fill}" font-size="10.5" font-weight="800" text-anchor="middle">${d.value}${opts.suffix||''}</text>
      <text x="${x+bw/2}" y="${h-9}" fill="#8b86a0" font-size="9.5" text-anchor="middle">${d.label}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">${bars}</svg>`;
}
function dchHBarChart(items){
  const w = 580, rowH = 30, h = items.length * rowH + 16;
  const max = Math.max.apply(null, items.map(d=>d.value));
  const labelW = 200, valW = 70, trkX = labelW, trkW = w - labelW - valW;
  const rows = items.map((d,i) => {
    const cy = 10 + i*rowH;
    const bw = (d.value / max) * trkW;
    return `<text x="0" y="${cy+15}" fill="#3c3654" font-size="11.5" font-weight="700">${d.label}</text>
      <rect x="${trkX}" y="${cy+6}" width="${trkW}" height="14" rx="7" fill="#F2EFF8"/>
      <rect x="${trkX}" y="${cy+6}" width="${bw}" height="14" rx="7" fill="url(#dchHbar)"/>
      <text x="${w}" y="${cy+15}" fill="#1c1530" font-size="11.5" font-weight="800" text-anchor="end">${d.value}${d.suffix||''}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
    <defs><linearGradient id="dchHbar" x1="0" x2="1"><stop offset="0" stop-color="#5C18AB"/><stop offset="1" stop-color="#0071B0"/></linearGradient></defs>
    ${rows}
  </svg>`;
}
function dchDonutChart(parts, label){
  // parts = [{label,value,color}]
  const total = parts.reduce((s,p)=>s+p.value, 0) || 1;
  const r = 64, c = 84, cx = c, cy = c, circ = 2*Math.PI*r;
  let off = 0;
  const arcs = parts.map(p => {
    const len = circ * (p.value/total);
    const seg = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${p.color}" stroke-width="22" stroke-dasharray="${len} ${circ-len}" stroke-dashoffset="${-off}" transform="rotate(-90 ${cx} ${cy})"/>`;
    off += len;
    return seg;
  }).join('');
  const legend = parts.map(p => `<div style="display:flex;align-items:center;gap:6px;font-size:11.5px;color:#3c3654;font-weight:700"><span style="width:10px;height:10px;border-radius:3px;background:${p.color}"></span>${p.label} · <b style="color:#1c1530">${p.value}</b></div>`).join('');
  return `<div style="display:flex;align-items:center;gap:20px;justify-content:center;flex-wrap:wrap">
    <svg viewBox="0 0 ${c*2} ${c*2}" style="width:170px;height:170px">
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#F2EFF8" stroke-width="22"/>
      ${arcs}
      <text x="${cx}" y="${cy-4}" fill="#1c1530" font-size="22" font-weight="800" text-anchor="middle">${total}</text>
      <text x="${cx}" y="${cy+15}" fill="#8b86a0" font-size="10" font-weight="700" text-anchor="middle" letter-spacing="0.5">${label||'TOTAL'}</text>
    </svg>
    <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-start">${legend}</div>
  </div>`;
}
function dchGroupedBarChart(groups, series){
  // groups: [{label}], series: [{name, color, values: [..]}]
  const w = 580, h = 220, pad = 36;
  const max = Math.max.apply(null, series.flatMap(s=>s.values)) * 1.15 + 1;
  const gw = (w - pad*2) / groups.length;
  const bw = gw / (series.length + 1.4);
  const y = v => h - pad - (v / max) * (h - pad*2 - 16);
  const bars = groups.map((g,gi) => {
    const gx = pad + gi*gw + (gw - bw*series.length)/2;
    return series.map((s,si) => {
      const v = s.values[gi] || 0;
      const x = gx + si*bw;
      const yy = y(v);
      const bh = Math.max(1, h - pad - yy);
      return `<rect x="${x}" y="${yy}" width="${bw-3}" height="${bh}" rx="3" fill="${s.color}" opacity=".92"/>
        <text x="${x + (bw-3)/2}" y="${yy-3}" fill="${s.color}" font-size="9" font-weight="800" text-anchor="middle">${v}</text>`;
    }).join('') + `<text x="${gx + (bw*series.length)/2}" y="${h-10}" fill="#3c3654" font-size="11" font-weight="700" text-anchor="middle">${g.label}</text>`;
  }).join('');
  const legend = series.map(s => `<span style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;color:#3c3654;margin-right:14px"><span style="width:10px;height:10px;border-radius:3px;background:${s.color}"></span>${s.name}</span>`).join('');
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">${bars}</svg>
    <div style="text-align:center;margin-top:4px">${legend}</div>`;
}
function dchForecastChart(past, fut, futLo, futHi, pastLabels, futLabels){
  const w = 580, h = 200, pad = 30;
  const all = past.concat(fut, futHi);
  const max = Math.max.apply(null, all) * 1.1;
  const min = Math.min.apply(null, all.concat(futLo)) * 0.85;
  const total = past.length + fut.length;
  const xStep = (w - pad*2) / (total - 1);
  const y = v => h - pad - (v - min) / (max - min) * (h - pad*2 - 14);
  const xp = i => pad + i * xStep;
  const pastPts = past.map((v,i) => `${xp(i)},${y(v)}`).join(' ');
  const futPts = fut.map((v,i) => `${xp(past.length+i)},${y(v)}`).join(' ');
  const bridge = `${xp(past.length-1)},${y(past[past.length-1])} ${xp(past.length)},${y(fut[0])}`;
  let bandPath = '';
  if (fut.length >= 2){
    const lo = fut.map((_,i)=>`${xp(past.length+i)},${y(futLo[i])}`).join(' L');
    const hi = fut.map((_,i)=>`${xp(past.length+i)},${y(futHi[i])}`).reverse().join(' L');
    bandPath = `M${lo} L${hi} Z`;
  }
  const all2 = pastLabels.concat(futLabels);
  const tks = all2.map((m,i) => `<text x="${xp(i)}" y="${h-9}" fill="#8b86a0" font-size="10" text-anchor="middle">${m}</text>`).join('');
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
    <defs><linearGradient id="dchFc" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#0071B0" stop-opacity=".28"/><stop offset="1" stop-color="#0071B0" stop-opacity=".04"/></linearGradient></defs>
    <path d="${bandPath}" fill="url(#dchFc)"/>
    <polyline points="${pastPts}" fill="none" stroke="#5C18AB" stroke-width="2.6"/>
    <polyline points="${bridge}" fill="none" stroke="#0071B0" stroke-width="2.4" stroke-dasharray="5 4"/>
    <polyline points="${futPts}" fill="none" stroke="#0071B0" stroke-width="2.6" stroke-dasharray="5 4"/>
    ${past.map((v,i)=>`<circle cx="${xp(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#5C18AB" stroke-width="2.2"/><text x="${xp(i)}" y="${y(v)-9}" fill="#5C18AB" font-size="10" font-weight="800" text-anchor="middle">${v}</text>`).join('')}
    ${fut.map((v,i)=>`<circle cx="${xp(past.length+i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#0071B0" stroke-width="2.2"/><text x="${xp(past.length+i)}" y="${y(v)-9}" fill="#0071B0" font-size="10" font-weight="800" text-anchor="middle">${v}</text>`).join('')}
    <text x="${xp(past.length-1)+xStep/2}" y="20" fill="#8b86a0" font-size="10" font-weight="700">Forecast →</text>
    ${tks}
  </svg>`;
}

/* ---- Intent matcher ---- */
function dchMatchIntent(q){
  const s = (q||'').toLowerCase();
  // Order matters: more specific intents BEFORE generic ones.
  if (/(complic|advers|event|severe|critic)/.test(s)) return 'complications';
  // By-doctor intent (must come before 'outcomesType' so phrases like "outcomes by doctor" route correctly)
  if (/(by\s+doctor|per\s+doctor|by\s+surgeon|per\s+surgeon|surgeon\s+results|doctors?\s+stats|por\s+m[eé]dico|por\s+doctor|por\s+cirujano|resultados?\s+por\s+m[eé]dico)/.test(s)) return 'byDoctor';
  if (/(outcomes?\s+por\s+tipo|por\s+tipo\s+de\s+cirug|cataract\s+vs|lasik\s+vs|smile\s+vs|outcomes?\s+comparat)/.test(s)) return 'outcomesType';
  if (/(mix|distribuc|breakdown)/.test(s) && /(cirug|surger)/.test(s)) return 'mix';
  // Geo intent (must come before generic 'traits' / 'dissat' matchers)
  if (/(mapa|map|geogr|d[oó]nde|where|provinc|ciudad|regi[oó]n|argentin)/.test(s)) return 'geo';
  if (/(caracter|trait|charact|comun|common|perfil)/.test(s) && /(insatisf|descont|dissat|unhappy)/.test(s)) return 'traits';
  if (/(insatisf|descont|dissat|unhappy|worst|quej|complain)/.test(s)) return 'dissat';
  if (/(lasik|smile|refract)/.test(s) && /(outcome|result|c[oó]mo|hi[cw]ieron|est[aá]n)/.test(s)) return 'refractiveOutcomes';
  if (/(sobre|sub|over|under).{0,8}(correc|correction)/.test(s) || /(residual|residuo).{0,15}(refract)/.test(s)) return 'overUnder';
  if (/(iol|lens|lente|model|modelo|benchmark)/.test(s) && /(satisf|6\s*me|6\s*mo|mejor|best|outcome|compar|benchmark)/.test(s)) return 'bestIol';
  if (/(evolu|trend|mes\s+a\s+mes|month|monthly|growth|crecim)/.test(s)) return 'evolution';
  if (/(vault|accuracy|precis)/.test(s) || (/(surgeon|cirujan)/.test(s) && /(icl|vault)/.test(s))) return 'vault';
  if (/(overdue|retras|vencid|atras|late|post.?op)/.test(s)) return 'overdue';
  if (/(pipeline|funnel|funel|flujo)/.test(s) || (/(esta\s+semana|this\s+week)/.test(s) && /(paciente|patient|case)/.test(s))) return 'pipeline';
  if (/(forecast|próximo|proximo|trimestr|quarter|projec|predic|pronost)/.test(s)) return 'forecast';
  if (/(nps|net\s+promot|benchmark|peer|compar|similar)/.test(s)) return 'nps';
  return 'fallback';
}

/* ---- Answer dispatcher ---- */
function dchAnswer(intent, q){
  switch(intent){
    case 'dissat':              return dchAnsDissat();
    case 'traits':              return dchAnsTraits();
    case 'mix':                 return dchAnsMix();
    case 'evolution':           return dchAnsEvolution();
    case 'vault':               return dchAnsVault();
    case 'overdue':             return dchAnsOverdue();
    case 'pipeline':            return dchAnsPipeline();
    case 'bestIol':             return dchAnsBestIol();
    case 'forecast':            return dchAnsForecast();
    case 'complications':       return dchAnsComplications();
    case 'nps':                 return dchAnsNps();
    case 'outcomesType':        return dchAnsOutcomesByType();
    case 'refractiveOutcomes':  return dchAnsRefractiveOutcomes();
    case 'overUnder':           return dchAnsOverUnder();
    case 'geo':                 return dchAnsGeo();
    case 'byDoctor':            return dchAnsByDoctor();
    default:                    return dchAnsFallback(q);
  }
}

function dchEsc(s){ return String(s).replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function dchCite(){ return `<div class="dch-cite">Source: <span class="dch-srcpill">EVO Vault</span><span class="dch-srcpill">${dchDisplayTotal()} cases</span><span class="dch-srcpill">last 12 months</span></div>`; }
